-- Sequence revive wave-2 i18n — be literals (app.* keys, public.translations,
-- 7 languages incl. pt-PT): moment/mode label pairs + tooltip keys + the
-- wave-2 validation kmsg keys the guarded update path emits.

DELETE FROM public.translations
WHERE key IN (
  'app.entities.sequence.fields.expire_at',
  'app.entities.sequence.fields.switch_at',
  'app.entities.sequence.fields.revive_every',
  'app.entities.sequence.fields.revive_grace'
);

